/**
 * Ulaanbaatar corridor graph.
 *
 * Node coordinates are demo-grade (placed by hand from public geography, +/- a few
 * hundred metres). Route shapes are generated by walking this graph. Nothing here is
 * real UB service data - see the DEMO badge and the Settings provenance panel.
 *
 * Place names that appear in the source material are used verbatim so the demo
 * echoes the deck: Peace Ave, Bayankhoshuu Rd, Bayangol, 5th khoroo (S5, S9).
 */

export interface Node {
  id: string;
  name_en: string;
  name_mn: string;
  lon: number;
  lat: number;
  /** 0 = outer, 1 = mid, 2 = central. Drives demand weight and congestion. */
  centrality: 0 | 1 | 2;
  district: string;
}

