/** Nodes far enough out that a route touching one counts as suburban. */
export const OUTER = new Set([
  'n-emeelt', 'n-songino', 'n-nalaikh', 'n-shadivlan', 'n-buyant', 'n-nisekh',
  'n-zaisan', 'n-bkh-3', 'n-dambadarjaa', 'n-tolgoit-e', 'n-amgalan',
]);

export const NODE_BY_ID = new Map(NODES.map((n) => [n.id, n]));

export const ADJ: Map<string, string[]> = (() => {
  const m = new Map<string, string[]>();
  for (const n of NODES) m.set(n.id, []);
  for (const [a, b] of EDGES) {
    m.get(a)!.push(b);
    m.get(b)!.push(a);
  }
  return m;
})();

